script:
frappe.ui.form.on("Loan Bank Reconciliation", {
    refresh(frm) {
        if (frm.is_new()) return;
        frm.add_custom_button("Import BSP Statement", () => {
            if (!frm.doc.statement_file) {
                frappe.msgprint("Attach the BSP statement CSV, then save this reconciliation first.");
                return;
            }
            frappe.call({
                method: "comfort_homes.api.loan_reconciliation",
                args: {name: frm.doc.name, action: "import_statement"},
                freeze: true,
                freeze_message: "Importing BSP credits…",
                callback(r) {
                    if (!r.exc) {
                        frappe.show_alert({message: `${r.message.imported} credits imported. ${r.message.ready} ready; ${r.message.review} need review.`, indicator: "green"});
                        frm.reload_doc();
                    }
                }
            });
        }, "Actions");
        if (frm.doc.transactions && frm.doc.transactions.length) {
            frm.add_custom_button("Create Loan Repayments", () => {
                frappe.confirm(
                    "Create repayments for every selected row with a Loan to Repay? Rows without a selected loan will remain for review.",
                    () => frappe.call({
                        method: "comfort_homes.api.loan_reconciliation",
                        args: {name: frm.doc.name, action: "create_repayments"},
                        freeze: true,
                        freeze_message: "Creating loan repayments…",
                        callback(r) {
                            if (!r.exc) {
                                const errors = r.message.errors || [];
                                const message = `${r.message.created} repayment(s) created. ${r.message.skipped} row(s) skipped.` + (errors.length ? `<br><br>${errors.join("<br>")}` : "");
                                frappe.msgprint({title: "Loan reconciliation", message, indicator: errors.length ? "orange" : "green"});
                                frm.reload_doc();
                            }
                        }
                    })
                );
            }, "Actions");
        }
    }
});

frappe.ui.form.on("Loan Bank Reconciliation Item", {
    loan(frm, cdt, cdn) {
        const row = locals[cdt][cdn];
        if (row.loan && !row.loan_repayment) {
            frappe.model.set_value(cdt, cdn, "selected", 1);
            frappe.model.set_value(cdt, cdn, "status", "Ready");
        }
    }
});
